function save(){ $('#balance').textContent=fmt(state.balance)}
function value(id){return Number(state.prices[id]??itemById(id)?.value??0)}
function publishDrop(...args){if(typeof recordDrop==='function')recordDrop(...args);}
function caseCharge(c){return (state.caseTickets?.[c.id]||0)>0?0:casePrice(c);}
function upgradeStake(inv){return inv?value(inv.id)+round(Math.max(0,Math.min(state.balance,Number(upgradeCoins)||0))):0;}
function upgradeProbability(inv,target){return inv&&target&&value(target.id)>value(inv.id)?Math.min(.75,(1-CONFIG.upgradeEdge)*upgradeStake(inv)/value(target.id)):0;}
function casePrice(c){return c.freeType?0:Number(state.casePrices[c.id]??c.price)}
function log(type,text,amount=0,proof=null){state.history.unshift({id:uid(),type,text,amount,at:Date.now(),...(proof?{proof}: {})});state.history=state.history.slice(0,120);save()}
function toast(text,error=false){if(error)SFX.play('error');const e=document.createElement('div');e.className='toast'+(error?' error':'');e.textContent=text;$('#toasts').append(e);setTimeout(()=>e.remove(),4200)}

const SFX=(()=>{
 let ctx,enabled=true,volume=.78;
 try{const saved=JSON.parse(localStorage.getItem('rot-audio')||'{}');enabled=saved.enabled!==false;if(saved.version===2&&Number.isFinite(saved.volume))volume=Math.max(0,Math.min(1,saved.volume));}catch{}
 function persist(){try{localStorage.setItem('rot-audio',JSON.stringify({enabled,volume,version:2}))}catch{}}
 function context(){try{const AC=window.AudioContext||window.webkitAudioContext;if(!AC)return null;if(!ctx||ctx.state==='closed')ctx=new AC();return ctx}catch{return null}}
 function unlock(){if(!enabled)return;const c=context();if(c?.state==='suspended'||c?.state==='interrupted')c.resume().catch(()=>{});}
 function note(freq,at,duration,gain=.25,type='sine'){const osc=ctx.createOscillator(),envelope=ctx.createGain();osc.type=type;osc.frequency.setValueAtTime(freq,at);envelope.gain.setValueAtTime(.0001,at);envelope.gain.exponentialRampToValueAtTime(Math.max(.0001,gain*volume),at+Math.min(.002,duration*.12));envelope.gain.exponentialRampToValueAtTime(.0001,at+duration);osc.connect(envelope);envelope.connect(ctx.destination);osc.start(at);osc.stop(at+duration+.025);}

 let clickNoise=null;
 function dryClick(kind,at,gain){if(!ctx.createBufferSource||!ctx.createBuffer||!ctx.createBiquadFilter)return false;if(!clickNoise){clickNoise=ctx.createBuffer(1,Math.ceil(ctx.sampleRate*.045),ctx.sampleRate);const data=clickNoise.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=Math.random()*2-1;}const duration=kind==='tick'?.013:.022,source=ctx.createBufferSource(),filter=ctx.createBiquadFilter(),envelope=ctx.createGain();source.buffer=clickNoise;filter.type='bandpass';filter.frequency.setValueAtTime(kind==='tick'?2700:1900,at);filter.Q.setValueAtTime(.65,at);envelope.gain.setValueAtTime(.0001,at);envelope.gain.exponentialRampToValueAtTime(Math.max(.0001,gain*volume),at+.0007);envelope.gain.exponentialRampToValueAtTime(.0001,at+duration);source.connect(filter);filter.connect(envelope);envelope.connect(ctx.destination);source.start(at);source.stop(at+duration+.003);return true;}
 function play(kind,weight=1){if(!enabled||volume<=0)return;const c=context();if(!c)return;const schedule=()=>{if(c.state!=='running')return;const t=c.currentTime+.006;if((kind==='tap'||kind==='tick')&&dryClick(kind,t,(kind==='tick'?.34:.28)*Math.max(0,Math.min(1,Number(weight)||0))))return;const patterns={tap:[[1800,0,.016,.14,'triangle']],tick:[[2400,0,.010,.14,'triangle']],start:[[660,0,.038,.17,'triangle'],[880,.035,.04,.15,'triangle']],gem:[[1320,0,.045,.16,'triangle'],[1760,.035,.05,.13,'triangle']],win:[[880,0,.055,.18,'triangle'],[1175,.045,.06,.16,'triangle'],[1568,.09,.085,.15,'triangle']],lose:[[440,0,.045,.18,'triangle'],[330,.045,.045,.17,'triangle'],[220,.09,.055,.15,'triangle']],error:[[380,0,.035,.17,'triangle'],[380,.065,.035,.16,'triangle']]};for(const [f,delay,d,g,type]of patterns[kind]||patterns.tap)note(f,t+delay,d,g*Math.max(0,Math.min(1,Number(weight)||0)),type||'sine');};if(c.state==='suspended'||c.state==='interrupted')c.resume().then(schedule).catch(()=>{});else schedule();}
 function update(){const b=$('#soundToggle');if(b){b.innerHTML=icon(enabled&&volume>0?'volume':'mute');b.setAttribute('aria-label',enabled?'Выключить звук':'Включить звук');b.title=enabled?'Звук: '+Math.round(volume*100)+'%':'Звук выключен';}}
 function toggle(){enabled=!enabled;persist();update();if(enabled){unlock();play('gem');}}
 function setVolume(n){volume=Math.max(0,Math.min(1,Number(n)||0));enabled=volume>0;persist();update();}
 function test(){if(!enabled||volume===0){enabled=true;volume=.78;persist();update();}unlock();play('win');}
 function ticks(duration){let elapsed=0,next=0;const id=setInterval(()=>{elapsed+=25;if(elapsed>=duration){clearInterval(id);return}if(elapsed>=next){play('tick');next=elapsed+55+Math.pow(elapsed/duration,3)*380}},25);return id;}
 document.addEventListener('pointerdown',unlock,{capture:true});document.addEventListener('keydown',unlock,{capture:true});
 return{play,toggle,ticks,update,setVolume,test,get volume(){return volume}};
})();
function ensureReferralState(){if(!state.referrals)state.referrals={code:'DEMO0001',available:82.5,earned:147.5,transferred:65,people:[{name:'pixel_fox',joined:'2026-10-23',deposited:800,spent:620,won:280,percent:null,codeUses:2,bonus:16.2},{name:'mango.exe',joined:'2026-10-25',deposited:500,spent:450,won:120,percent:7,codeUses:1,bonus:13.5},{name:'noobini_fan',joined:'2026-10-27',deposited:1200,spent:850,won:940,percent:null,codeUses:3,bonus:25.5},{name:'cube_04',joined:'2026-10-29',deposited:400,spent:250,won:80,percent:null,codeUses:1,bonus:7.5}],history:[{at:Date.now()-86400000,type:'Начисление за неделю',amount:82.5},{at:Date.now()-4*86400000,type:'Перевод на основной баланс',amount:-65},{at:Date.now()-6*86400000,type:'Начисление за неделю',amount:65}]};}
let refRange='week';
function pickerToolbar(kind){return `<label class="search picker-search">${icon('search')}<input placeholder="Найти предмет" aria-label="Поиск предмета" data-picker="${kind}" value="${esc(pickerFilters[kind]||'')}"></label>`}
function inventoryCards(kind){let inv=state.inventory.filter(i=>itemById(i.id).name.toLowerCase().includes((pickerFilters[kind]||'').toLowerCase())).sort((a,b)=>(value(a.id)-value(b.id))*(pickerFilters[kind+'Sort']==='desc'?-1:1));return inv.length?inv.map(i=>{const p=itemById(i.id);return petCard(p,`data-inline-select="${i.uid}" data-kind="${kind}" aria-pressed="${selection[kind]===i.uid}"`).replace('class="pet"',`class="pet ${selection[kind]===i.uid?'selected':''}"`)}).join(''):'<div class="inventory-empty">Нет подходящих предметов</div>'}
function targetCards(){const inv=state.inventory.find(i=>i.uid===selection.upgrade);if(!inv)return '<div class="inventory-empty">Сначала выбери свой предмет</div>';const list=CONFIG.items.filter(p=>value(p.id)>value(inv.id)&&p.name.toLowerCase().includes((pickerFilters.target||'').toLowerCase())).sort((a,b)=>(value(a.id)-value(b.id))*(pickerFilters.targetSort==='desc'?-1:1));return list.length?list.map(p=>petCard(p,`data-inline-target="${p.id}" aria-pressed="${selection.target===p.id}"`).replace('class="pet"',`class="pet ${selection.target===p.id?'selected':''}"`)).join(''):'<div class="inventory-empty">Подходящих целей нет</div>'}
