function referralRows(){const factor=refRange==='week'?1:2.4;return state.referrals.people.map(p=>{const deposited=round(p.deposited*factor),spent=round(p.spent*factor),won=round(p.won*factor),loss=Math.max(0,Math.min(deposited,spent-won)),percent=p.percent??state.settings.referralPercent,earned=round(loss*percent/100),bonus=round(deposited*state.settings.partnerBonus/100);return {...p,deposited,spent,won,loss,percent,earned,bonus}})}
function renderReferrals(){const r=state.referrals,rows=referralRows(),pre=round(rows.reduce((s,p)=>s+p.earned,0)),promo=round(rows.reduce((s,p)=>s+p.bonus,0));return `<div class="page-heading"><div><h1 class="page-title">Реферальный кабинет</h1><span class="subtle">Тестовые данные партнёрской программы</span></div><button class="btn secondary small" data-action="ref-help">${icon('help')}Расчёт дохода</button></div><div class="ref-top-grid"><section class="panel ref-link-panel"><div class="panel-heading"><h3>Твоя ссылка и код</h3><span class="tiny-neutral">Партнёр</span></div><button class="ref-code" data-action="copy-code">${esc(r.code)} ${icon('copy')}</button><div class="copy-row"><input readonly aria-label="Реферальная ссылка" value="https://t.me/your_bot/app?startapp=${r.code}"><button class="btn secondary" data-action="copy-ref">${icon('copy')}</button></div><div class="ref-rates"><div><strong>${state.settings.referralPercent}%</strong><span>от чистого проигрыша</span></div><div><strong>${state.settings.promoBonus}%</strong><span>бонус приглашённому</span></div><div><strong>${state.settings.partnerBonus}%</strong><span>партнёру с пополнения</span></div></div></section><section class="panel ref-balance-panel"><span class="label">Доступно к переводу</span><div class="ref-big">${fmt(r.available)}<small>R</small></div><button class="btn wide" data-action="ref-transfer" ${r.available<=0?'disabled':''}>Перевести на баланс ${icon('arrow')}</button><div class="stat-line"><span>Переведено ранее</span><strong>${fmt(r.transferred)} R</strong></div></section></div><div class="section-head"><h2>Статистика</h2><div class="tabs"><button class="chip ${refRange==='week'?'active':''}" data-ref-range="week">За 7 дней</button><button class="chip ${refRange==='month'?'active':''}" data-ref-range="month">За 30 дней</button></div></div><div class="stats-grid ref-stats">${[['users',r.people.length,'Приглашённых'],['wallet',fmt(pre)+' R','Расчёт с проигрышей'],['star',fmt(promo)+' R','Бонусы промокода'],['check',fmt(r.earned)+' R','Всего начислено']].map(([i,v,n])=>`<div class="stat-card">${icon(i)}<strong>${v}</strong><span>${n}</span></div>`).join('')}</div><section class="panel"><div class="panel-heading"><h3>Приглашённые</h3><span class="muted-small">Индивидуальные ставки отмечены отдельно</span></div><div class="table-wrap"><table class="ref-table"><thead><tr><th>ПОЛЬЗОВАТЕЛЬ</th><th>ПОПОЛНЕНО</th><th>ЧИСТЫЙ ПРОИГРЫШ</th><th>ТВОЙ %</th><th>ДОХОД</th><th>ПРОМОКОД</th></tr></thead><tbody>${rows.map(p=>`<tr><td><div class="ref-person"><span class="ref-avatar">${esc(p.name.slice(0,1).toUpperCase())}</span><div><strong>${esc(p.name)}</strong><small>с ${p.joined}</small></div></div></td><td>${fmt(p.deposited)} R</td><td>${fmt(p.loss)} R</td><td><span class="tiny-neutral ${p.name==='mango.exe'?'custom-rate':''}">${p.percent}%</span></td><td class="positive">${fmt(p.earned)} R</td><td>${p.codeUses} исп. · ${fmt(p.bonus)} R</td></tr>`).join('')}</tbody></table></div></section><section class="panel" style="margin-top:18px"><h3>История начислений и переводов</h3><div class="table-wrap"><table><thead><tr><th>ОПЕРАЦИЯ</th><th>ДАТА</th><th>СУММА</th></tr></thead><tbody>${r.history.map(h=>`<tr><td>${esc(h.type)}</td><td>${new Date(h.at).toLocaleString('ru-RU',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'})}</td><td class="${h.amount>0?'positive':'subtle'}">${h.amount>0?'+':''}${fmt(h.amount)} R</td></tr>`).join('')}</tbody></table></div></section><div class="muted-small" style="margin-top:16px">Статистика приглашённых — образец для демонстрации. Перевод меняет только тестовый баланс.</div>`}
