function go(id){if(busy||mine.active||crash.active){toast('Сначала заверши текущий раунд',true);return}if(page===id)return;page=id;location.hash=id;render();window.scrollTo({top:0,behavior:'instant'})}
let renderedPage=null;
function viewKey(node){if(node.nodeType!==1)return null;for(const attr of ['id','data-inline-select','data-inline-target','data-bulk-id','data-case','data-page','data-color','data-ref-tab','data-upgrade-tab']){const v=node.getAttribute(attr);if(v!==null)return node.tagName+':'+attr+':'+v;}return null;}
function patchViewNode(current,next){if(current.nodeType!==next.nodeType||current.nodeName!==next.nodeName){const copy=next.cloneNode(true);current.replaceWith(copy);return copy;}if(current.nodeType===3||current.nodeType===8){if(current.nodeValue!==next.nodeValue)current.nodeValue=next.nodeValue;return current;}if(current.nodeType!==1)return current;const keepStyle=current.classList?.contains('wheel-liquid');for(const attr of Array.from(current.attributes)){if(attr.name==='style'&&keepStyle)continue;if(!next.hasAttribute(attr.name))current.removeAttribute(attr.name);}for(const attr of Array.from(next.attributes)){if(attr.name==='style'&&keepStyle)continue;if(current.getAttribute(attr.name)!==attr.value)current.setAttribute(attr.name,attr.value);}patchViewChildren(current,next);if(current!==document.activeElement){if(current.tagName==='INPUT'){current.value=next.value;current.checked=next.checked;current.disabled=next.disabled;}else if(current.tagName==='SELECT'||current.tagName==='TEXTAREA')current.value=next.value;}return current;}
function patchViewChildren(parent,nextParent){const original=Array.from(parent.childNodes),keyed=new Map(original.map(n=>[viewKey(n),n]).filter(([k])=>k!==null));let cursor=parent.firstChild;for(const next of Array.from(nextParent.childNodes)){const key=viewKey(next);let current=key!==null?keyed.get(key):cursor;if(current&&key===null&&viewKey(current)!==null)current=null;if(current){if(current!==cursor)parent.insertBefore(current,cursor);const updated=patchViewNode(current,next);cursor=updated.nextSibling;if(key!==null)keyed.delete(key);}else{parent.insertBefore(next.cloneNode(true),cursor);}}while(cursor){const rest=cursor.nextSibling;parent.removeChild(cursor);cursor=rest;}}
function patchElementHTML(element,html){if(!element)return;const template=document.createElement('template');if(!template.content||!element.childNodes){element.innerHTML=html;return;}template.innerHTML=html;patchViewChildren(element,template.content);}
function updateMainHTML(html){const main=$('#main');if(renderedPage!==page){main.innerHTML=html;renderedPage=page;}else patchElementHTML(main,html);}
function render(){ensureReferralState();renderNav();$('#breadcrumb').textContent='Игровая / '+(NAV.find(n=>n[0]===page)?.[1]||({admin:'Студия',faq:'Как играть',referrals:'Реферальный кабинет'}[page]));updateMainHTML(`<div class="mobile-modes">${(['cases','upgrade','mines','dice','crash'].includes(page)?NAV.filter(n=>['cases','upgrade','mines','dice','crash'].includes(n[0])):[]).map(([id,n,i])=>`<button class="chip ${page===id?'active':''}" data-page="${id}">${icon(i)}${n}</button>`).join('')}</div><div class="page-in">${({cases:renderCases,inventory:renderInventory,dice:renderDice,mines:renderMines,upgrade:renderUpgrade,crash:renderCrash,profile:renderProfile,bonuses:renderBonuses,referrals:renderReferrals,admin:renderAdmin,faq:renderFAQ}[page]||renderCases)()}</div>`);hydrate();save();if(page==='cases')filterCases();if(page==='upgrade')animateWheelFill();}
function showModal(html,lock=false){$('#dialogBody').innerHTML=html;$('.dialog').classList.toggle('case-dialog',html.includes('case-opening'));$('#modal').hidden=false;modalLocked=lock;document.documentElement.classList.add('modal-open');hydrate();setTimeout(()=>$('#modal .close').focus(),0)}
function closeModal(){if(modalLocked){toast('Дождись результата');return}$('#modal').hidden=true;document.documentElement.classList.remove('modal-open');document.body.style.overflow='';}
function petCard(p,attrs='',inv=null){return `<button class="pet" style="--accent:${colors[p.tier]}" ${attrs}>${petArt(p)}<div class="pet-name">${esc(p.name)}</div><div class="pet-value">${fmt(value(p.id))} R</div>${inv?'<span class="muted-small">В инвентаре</span>':''}</button>`}
function title(name,sub){return `<h1 class="page-title">${name}</h1><div class="subtle">${sub}</div>`}
function renderCases(){return `<div class="page-heading"><div><h1 class="page-title">Кейсы</h1><span class="subtle">${CONFIG.cases.length} кейсов</span></div><label class="search">${icon('search')}<input id="caseSearch" aria-label="Поиск кейса" placeholder="Найти кейс" value="${esc(query)}"></label></div><div class="case-grid" id="caseGrid"></div>`}
function filterCases(){let list=CONFIG.cases.filter(c=>(category==='all'||c.tier===Number(category))&&c.name.toLowerCase().includes(query.toLowerCase()));if(sort!=='default')list.sort((a,b)=>(casePrice(a)-casePrice(b))*(sort==='cheap'?1:-1));$('#caseGrid').innerHTML=list.length?list.map(c=>`<button class="case-card" style="--accent:${colors[c.tier]}" data-case="${c.id}"><span class="tiny-tag">${CONFIG.rarities[c.tier]}</span><div class="case-art">${caseArt(c)}</div><h3>${esc(c.name)}</h3><div class="price-row"><span>Открыть</span><span class="price"><span class="coin">R</span>${fmt(casePrice(c))}</span></div><div class="rarity-bar"></div></button>`).join(''):'<p class="subtle">Ничего не найдено. Попробуй другое название.</p>'}
function reelCard(p){return `<div class="pet reel-pet" style="--accent:${colors[p.tier]}">${petArt(p)}<div class="pet-name">${esc(p.name)}</div><div class="pet-value">${fmt(value(p.id))} R</div></div>`}
function openCase(id){const c=CONFIG.cases.find(x=>x.id===id);if(!c)return;const preview=Array.from({length:12},(_,n)=>itemById(c.drops[n%c.drops.length].id));showModal(`<div class="case-opening"><div class="case-opening-head"><div><span class="tiny-tag" style="--accent:${colors[c.tier]}">${CONFIG.rarities[c.tier]}</span><h2 id="dialogTitle">${esc(c.name)}</h2></div><span class="case-opening-price">${fmt(casePrice(c))} R</span></div><div class="reel-window" id="caseReelWindow"><div class="reel-marker"></div><div class="reel" id="caseReel">${preview.map(reelCard).join('')}</div></div><button class="btn wide" id="caseOpen" data-open="${id}" ${state.balance<caseCharge(c)?'disabled':''}>Открыть · ${fmt(caseCharge(c))} R</button><div class="case-contents-title">Содержимое кейса <span>${c.drops.length} предметов</span></div><div class="pet-grid case-contents">${c.drops.map(d=>{const p=itemById(d.id);return `<div class="pet" style="--accent:${colors[p.tier]}">${petArt(p)}<div class="pet-name">${esc(p.name)}</div><div class="pet-value">${fmt(value(p.id))} R</div></div>`}).join('')}</div></div>`)}
function weighted(drops,draw=random()){let n=draw*drops.reduce((s,d)=>s+d.weight,0);for(const d of drops){n-=d.weight;if(n<0)return d.id}return drops.at(-1).id}
function rollCase(id){if(busy)return;const c=CONFIG.cases.find(x=>x.id===id),price=caseCharge(c);if(state.balance<price)return toast('Не хватает тестового баланса',true);busy=true;modalLocked=true;SFX.play('start');if(price===0&&state.caseTickets?.[c.id]>0)state.caseTickets[c.id]--;state.balance=round(state.balance-price);const winner=itemById(weighted(c.drops)),inv=makeInv(winner.id);state.inventory.push(inv);state.stats.cases++;log('case',c.name+' → '+winner.name,-price);
const reel=Array.from({length:40},()=>itemById(weighted(c.drops)));reel[33]=winner;const track=$('#caseReel');track.style.transition='none';track.style.transform='translateX(0px)';track.innerHTML=reel.map(reelCard).join('');$('#caseReelWindow').classList.remove('revealed');$('#caseOpen').disabled=true;$('#caseOpen').textContent='Открывается…';
requestAnimationFrame(()=>requestAnimationFrame(()=>{const w=$('#caseReelWindow').clientWidth;track.style.transition='transform 4.8s cubic-bezier(.10,.70,.12,1)';track.style.transform=`translateX(${w/2-10-33*134-63}px)`}));const reelTicks=SFX.ticks(4500);
setTimeout(()=>{clearInterval(reelTicks);SFX.play('win');publishDrop(winner.id,'Кейс · '+c.name);busy=false;modalLocked=false;$('#caseReelWindow').classList.add('revealed');toast(winner.name+' · '+fmt(value(winner.id))+' R · В инвентаре');$('#caseOpen').disabled=state.balance<caseCharge(c);$('#caseOpen').textContent='Открыть · '+fmt(caseCharge(c))+' R';},4900);
}
function renderInventory(){return `${title('Инвентарь','Выбирай предмет, чтобы продать, обменять или посмотреть подробнее.')}<div class="section-head"><div class="tabs"><span class="chip active">Все предметы · ${state.inventory.length}</span></div><div class="price">${icon('bag')} ${fmt(state.inventory.reduce((s,i)=>s+value(i.id),0))} R</div></div>${state.inventory.length?`<div class="pet-grid">${[...state.inventory].reverse().map(i=>petCard(itemById(i.id),`data-inv="${i.uid}"`)).join('')}</div>`:`<div class="panel inventory-empty">${icon('bag')}Пока пусто. Открой кейс, чтобы начать коллекцию.<br><button class="btn" style="margin-top:20px" data-page="cases">К кейсам</button></div>`}`}
function viewItem(id){const inv=state.inventory.find(x=>x.uid===id);if(!inv)return;const p=itemById(inv.id);showModal(`<div class="result-display"><h2 id="dialogTitle">${esc(p.name)}</h2>${petArt(p,'pet-art',true)}<span class="tiny-tag" style="--accent:${colors[p.tier]}">${CONFIG.rarities[p.tier]}</span><h3>${fmt(value(p.id))} R</h3><div class="inline-actions"><button class="btn" data-sell="${id}">Продать</button><button class="btn secondary" data-exchange="${id}">${icon('swap')}Обменять</button><button class="btn secondary" data-withdraw="${id}">${icon('external')}Вывести</button></div><p class="muted-small">${p.seed%3===0?'Доступен для тестовой заявки на вывод':'Доступна продажа или обмен на выводимый предмет'}</p></div>`)}
function sell(id){const index=state.inventory.findIndex(x=>x.uid===id);if(index<0)return;const i=state.inventory[index],p=itemById(i.id);state.inventory.splice(index,1);const n=value(i.id);state.balance=round(state.balance+n);log('sale','Продажа '+p.name,n);closeModal();render();toast('Продано за '+fmt(n)+' R')}
function exchangeQuote(fromId,to){const target=itemById(to),source=Math.round(value(fromId)*100),unit=Math.round(value(to)*100);if(!target||target.seed%3!==0||!Number.isSafeInteger(source)||!Number.isSafeInteger(unit)||unit<=0||unit>=source)return null;const count=Math.min(5,Math.floor(source/unit));if(count<1)return null;return{count,remainder:(source-count*unit)/100,total:count*unit/100};}
function exchange(id){const inv=state.inventory.find(x=>x.uid===id);if(!inv)return;const p=itemById(inv.id),options=CONFIG.items.map(x=>({p:x,q:exchangeQuote(inv.id,x.id)})).filter(x=>x.q).sort((a,b)=>value(b.p.id)-value(a.p.id));showModal(`<h2 id="dialogTitle">Обмен предмета</h2><p class="subtle">${esc(p.name)} · ${fmt(value(p.id))} R</p><div class="exchange-explanation">До 5 более дешёвых предметов. Остаток стоимости — монетами на баланс.</div>${options.length?`<div class="pet-grid exchange-options">${options.map(({p:x,q})=>`<button class="pet exchange-option" style="--accent:${colors[x.tier]}" data-exchange-to="${x.id}" data-source="${id}"><span class="exchange-quantity">×${q.count}</span>${petArt(x)}<div class="pet-name">${esc(x.name)}</div><div class="pet-value">${q.count} × ${fmt(value(x.id))} R</div><div class="exchange-remainder">${q.remainder?'+ '+fmt(q.remainder)+' R':'Без остатка'}</div></button>`).join('')}</div>`:'<div class="inventory-empty">Нет более дешёвых предметов для обмена.</div>'}`)}
function doExchange(id,to){const index=state.inventory.findIndex(i=>i.uid===id);if(index<0)return;const from=state.inventory[index],quote=exchangeQuote(from.id,to);if(!quote)return toast('Этот вариант обмена недоступен',true);const prizes=Array.from({length:quote.count},()=>makeInv(to));state.inventory.splice(index,1,...prizes);state.balance=round(state.balance+quote.remainder);log('exchange',itemById(from.id).name+' → '+quote.count+' × '+itemById(to).name,quote.remainder);closeModal();render();SFX.play('gem');toast('Получено '+quote.count+' × '+itemById(to).name+(quote.remainder?' и '+fmt(quote.remainder)+' R':''))}
function withdraw(id){const i=state.inventory.find(x=>x.uid===id);if(!i)return;const p=itemById(i.id);if(p.seed%3!==0)return toast('Этот предмет доступен только для продажи и обмена',true);const last=state.withdrawals.at(-1)?.time||0;const time=Math.max(Date.now()+10*60000,last+4*60000);showModal(`<h2 id="dialogTitle">Тестовая запись</h2><div class="result-display">${petArt(p)}<h3>${esc(p.name)}</h3><p class="subtle">Ближайший интервал</p><h3>${new Date(time).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})} — ${new Date(time+4*60000).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})}</h3></div><div class="notice">Это демонстрация очереди. Реальная выдача в игре не выполняется.</div><button class="btn wide" data-book="${id}" data-time="${time}">Создать тестовую заявку</button>`)}
function book(id,time){const n=state.inventory.findIndex(i=>i.uid===id);if(n<0)return;const i=state.inventory.splice(n,1)[0];state.withdrawals.push({id:uid(),item:i,time:Number(time),status:'Демо-заявка'});log('withdraw','Тестовая заявка: '+itemById(i.id).name);closeModal();render();toast('Заявка записана. Её можно отменить в профиле')}
function selectedBox(kind,label='Выбрать предмет'){const inv=state.inventory.find(i=>i.uid===selection[kind]);return `<div class="selected-pet">${inv?petArt(itemById(inv.id)):`${icon('plus')}`}<div><strong>${inv?esc(itemById(inv.id).name):label}</strong><span>${inv?fmt(value(inv.id))+' R':'Из твоего инвентаря'}</span></div></div>`}
function pick(kind){if(busy||crash.active)return;if(kind==='target'){showModal(`<h2 id="dialogTitle">Цель апгрейда</h2><p class="subtle">Выбери предмет, который хочешь получить.</p><div class="pet-grid">${CONFIG.items.filter(p=>{const inv=state.inventory.find(i=>i.uid===selection.upgrade);return inv?value(p.id)>value(inv.id):true}).map(p=>petCard(p,`data-target="${p.id}"`)).join('')}</div>`);return}
 showModal(`<h2 id="dialogTitle">Выбери предмет</h2><p class="subtle">Ставка одним предметом из коллекции.</p>${state.inventory.length?`<div class="pet-grid">${state.inventory.map(i=>petCard(itemById(i.id),`data-select="${i.uid}" data-kind="${kind}"`)).join('')}</div>`:'<div class="inventory-empty">Нет предметов. Сначала открой кейс.</div>'}`)}
const DICE_COLORS=[['Orange','#ffab5b'],['Blue','#68a9ff'],['Green','#8bcb72'],['Red','#ef7784'],['Purple','#bc92f4'],['Yellow','#edda77']];let diceColor=1;
function diceCube(n,matched=false){return `<div class="die ${matched?'matched':''}" style="--c:${DICE_COLORS[n][1]}" role="img" aria-label="${esc(DICE_COLORS[n][0])}">${['front','right','top','left','bottom','back'].map((side,i)=>`<span class="cube-face cube-${side}" style="--face:${DICE_COLORS[(n+i)%6][1]}"></span>`).join('')}<span class="cube-result-label">${esc(DICE_COLORS[n][0])}</span></div>`;}
function renderDice(){const inv=state.inventory.find(i=>i.uid===selection.dice),stake=inv?value(inv.id):0;return `${title('Дайсы','1 или 4 совпадения — x2 предметами')}<div class="game-layout dice-layout"><section class="panel dice-controls"><div class="panel-heading"><h3>Ставка</h3><span class="tiny-neutral">1 предмет</span></div>${selectedBox('dice')}<span class="label">Выбери цвет</span><div class="color-grid">${DICE_COLORS.map(([n,c],i)=>`<button class="color-btn ${diceColor===i?'selected':''}" style="--c:${c}" data-color="${i}">${n}</button>`).join('')}</div><div class="outcome-preview"><span>При победе получишь</span>${inv?`<div class="prize-pair">${petArt(itemById(inv.id))}${petArt(itemById(inv.id))}<strong>×2</strong></div><strong>${esc(itemById(inv.id).name)}</strong>`:'<strong>2 × поставленный предмет</strong>'}<small>${stake?fmt(stake*2)+' R · ':''}Начисление в инвентарь</small></div><button class="btn wide" data-action="roll-dice" ${!inv?'disabled':''}>Бросить кубики ${icon('dice')}</button></section><section class="panel game-stage dice-stage"><div class="stage-topline"><span>${icon('dice')}Результат броска</span><span class="dice-rule-badge">1 / 4 = x2</span></div><div class="dice-tray" id="diceTray">${diceFaces.map(n=>diceCube(n,!!diceFeedback&&n===diceFeedback.color)).join('')}</div></section></div>${inlineInventory('dice','Мои предметы')}<details class="rules-inline"><summary>Правила и шансы</summary><p>1 или 4 совпадения: x2 в предметах. 0, 2 или 3: проигрыш. Каждый цвет равновероятен. Шанс победы — 38,66%. Ставка одним предметом; при победе в инвентарь добавляются два таких же.</p></details>`}
function takeItem(kind){const n=state.inventory.findIndex(i=>i.uid===selection[kind]);if(n<0){toast('Выбери предмет',true);return null}const i=state.inventory.splice(n,1)[0];selection[kind]=null;return i}
function rollDice(){if(busy)return;const chosen=diceColor,i=takeItem('dice');if(!i)return;busy=true;diceFeedback=null;state.stats.dice=(state.stats.dice||0)+1;state.stats.played++;log('dice','Ставка: '+itemById(i.id).name);SFX.play('start');$('#diceTray').classList.add('rolling');$$('.dice-layout button,.inline-inventory button,.inline-inventory input,.dice-controls button').forEach(b=>b.disabled=true);const result=Array.from({length:4},()=>Math.floor(random()*6));let ticks=0;const anim=setInterval(()=>{$$('#diceTray .die').forEach((d,j)=>d.style.setProperty('--c',DICE_COLORS[ticks>8?result[j]:Math.floor(random()*6)][1]));if(ticks%2===0)SFX.play('tick');ticks++},100);
 setTimeout(()=>{clearInterval(anim);diceFaces=result;const matches=result.filter(x=>x===chosen).length,win=matches===1||matches===4;if(win){state.inventory.push(makeInv(i.id),makeInv(i.id));publishDrop(i.id,'Дайсы',2)}diceFeedback={win,matches,color:chosen,item:i.id};log('dice',matches+' совпадений · '+(win?'Получено 2 × '+itemById(i.id).name:'Проигрыш'));busy=false;render();SFX.play(win?'win':'lose');toast(win?'Два предмета добавлены в инвентарь':'Ставка проиграна')},1500);
}
function renderMines(){return `${title('Мины','Поле 5 × 5. Забери монеты до попадания на мину.')}<div class="game-layout"><section class="panel"><h3>Настройки раунда</h3><label class="label" for="mineBet">Ставка в монетах</label><input id="mineBet" class="select-full" type="number" min="1" step="1" value="${mine.bet}"><label class="label" for="mineCount">Мин на поле</label><select id="mineCount" class="select-full">${[1,3,5,10].map(n=>`<option value="${n}" ${mine.count===n?'selected':''}>${n} из 25</option>`).join('')}</select><div class="stat-line"><span>Множитель</span><strong id="mineMult">x1.00</strong></div><div class="stat-line"><span>Забрать</span><strong id="mineReturn">0 R</strong></div><button class="btn wide" data-action="mine-start" id="mineAction">Начать раунд ${icon('grid')}</button><p class="muted-small">Коэффициент зависит от мин и открытых клеток. Демо-маржа: 6%.</p></section><section class="panel game-stage"><div class="mines-board">${Array.from({length:25},(_,i)=>`<button class="tile" data-tile="${i}" aria-label="Клетка ${i+1}" disabled></button>`).join('')}</div></section></div>`}
function mineMultiplier(open,count){let p=1;for(let n=0;n<open;n++)p*=(25-count-n)/(25-n);return open?Math.floor((1-CONFIG.minesEdge)/p*100)/100:1}
function mineStart(){if(mine.active)return mineCashout();const bet=Number($('#mineBet').value),count=Number($('#mineCount').value);if(!Number.isFinite(bet)||bet<1||bet>state.balance)return toast('Проверь сумму ставки',true);mine={active:true,finished:false,bombs:[],open:[],bet:round(bet),count,mult:1};while(mine.bombs.length<count){const n=Math.floor(random()*25);if(!mine.bombs.includes(n))mine.bombs.push(n)}state.balance=round(state.balance-mine.bet);state.stats.mines=(state.stats.mines||0)+1;state.stats.played++;log('mines','Начало раунда',-mine.bet);SFX.play('start');$$('.tile').forEach(b=>{b.disabled=false;b.className='tile';b.innerHTML=''});$('#mineBet').disabled=true;$('#mineCount').disabled=true;$('#mineAction').textContent='Забрать выигрыш';$('#mineAction').disabled=true;}
function mineTile(n){if(!mine.active||mine.open.includes(n))return;const btn=$(`[data-tile="${n}"]`);if(mine.bombs.includes(n)){SFX.play('lose');mine.active=false;mine.finished=true;revealMines();btn.classList.add('bomb');recordGameResult('mines',mine.bet,0);log('mines','Мина · проигрыш');$('#mineAction').textContent='Новый раунд';$('#mineAction').disabled=false;$('#mineBet').disabled=false;$('#mineCount').disabled=false;toast('Мина. Раунд закончен',true);return}SFX.play('gem');mine.open.push(n);btn.classList.add('safe');btn.innerHTML=icon('diamond');btn.disabled=true;mine.mult=mineMultiplier(mine.open.length,mine.count);$('#mineMult').textContent='x'+mine.mult.toFixed(2);$('#mineReturn').textContent=fmt(round(mine.bet*mine.mult))+' R';$('#mineAction').disabled=false;if(mine.open.length===25-mine.count)mineCashout()}
function revealMines(){$$('.tile').forEach(b=>{b.disabled=true;if(mine.bombs.includes(Number(b.dataset.tile))){b.classList.add('bomb');b.innerHTML=icon('bomb')}})}
function mineCashout(){if(!mine.active||!mine.open.length)return;const payout=round(mine.bet*mine.mult);state.balance=round(state.balance+payout);mine.active=false;mine.finished=true;revealMines();recordGameResult('mines',mine.bet,payout);log('mines','Забрано x'+mine.mult.toFixed(2),payout);publishDrop(null,'Мины',1,payout);SFX.play('win');$('#mineAction').textContent='Новый раунд';$('#mineBet').disabled=false;$('#mineCount').disabled=false;toast('Забрано '+fmt(payout)+' R')}
function animateWheelFill(){const fill=$('.wheel-liquid');if(!fill)return;const next=Math.max(0,Math.min(100,Number(fill.dataset.level)||0));fill.style.transition='none';fill.style.height=wheelFillPercent+'%';wheelFillPercent=next;requestAnimationFrame(()=>requestAnimationFrame(()=>{fill.style.transition='height .48s cubic-bezier(.2,.75,.2,1)';fill.style.height=next+'%'}));}
function renderUpgrade(){const target=itemById(selection.target),inv=state.inventory.find(x=>x.uid===selection.upgrade),chance=upgradeProbability(inv,target)*100;const inPet=inv&&itemById(inv.id);return `${title('Апгрейдер','')}<div class="upgrade-workspace" data-tab="${upgradeTab}"><div class="upgrade-mobile-tabs"><button class="${upgradeTab==='upgrade'?'active':''}" data-upgrade-tab="upgrade">1. Мой предмет</button><button class="${upgradeTab==='target'?'active':''}" data-upgrade-tab="target">2. Цель</button></div><section class="panel upgrade-list upgrade-mine"><div class="panel-heading"><h3>Мои предметы</h3><span class="tiny-neutral">${state.inventory.length}</span></div>${pickerToolbar('upgrade')}<div class="pet-grid inline-pets" id="list-upgrade">${inventoryCards('upgrade')}</div></section><section class="panel upgrade-console"><div class="upgrade-ring" id="upgradeRing" style="--chance:${chance || upgradeFeedback?.chance || 0}%"><div class="wheel-surface" aria-hidden="true"><div class="wheel-liquid" data-level="${chance || upgradeFeedback?.chance || 0}"><div class="wheel-meniscus"></div></div><div class="wheel-gloss"></div></div><div class="ring-content"><strong>${(chance || upgradeFeedback?.chance || 0).toFixed(1)}<small>%</small></strong><p>Шанс апгрейда</p></div><div class="upgrade-pointer" id="upgradePointer" style="transform:rotate(${upgradeAngle}deg)"><i></i></div></div><div class="upgrade-slots"><div class="upgrade-slot">${inPet?petArt(inPet):icon('plus')}<span>${inPet?esc(inPet.name):'Твой предмет'}</span><strong>${inPet?fmt(value(inPet.id))+' R':'—'}</strong></div>${icon('chevron')}<div class="upgrade-slot">${target?petArt(target):icon('plus')}<span>${target?esc(target.name):'Цель'}</span><strong>${target?fmt(value(target.id))+' R':'—'}</strong></div></div><div class="quick-chances">${[2,5,10].map(n=>`<button class="chip" data-mult="${n}">x${n}</button>`).join('')}${[30,50,75].map(n=>`<button class="chip" data-quick="${n}">${n}%</button>`).join('')}</div><div class="upgrade-boost"><label for="upgradeCoins">Добавить монеты</label><div><input id="upgradeCoins" type="number" min="0" max="${state.balance}" step=".01" value="${Math.max(0,Number(upgradeCoins)||0)}" aria-label="Монеты к ставке"><span>R</span></div></div><label class="fast-spin"><input type="checkbox" id="fastUpgrade" ${fastSpin?'checked':''}>Быстрый прокрут</label><button class="btn wide" id="upgradeGo" data-action="upgrade" ${!chance?'disabled':''}>Апгрейд ${icon('arrow')}</button></section><section class="panel upgrade-list upgrade-target"><div class="panel-heading"><h3>Цель апгрейда</h3><span class="tiny-neutral">Каталог</span></div>${pickerToolbar('target')}<div class="pet-grid inline-pets" id="list-target">${targetCards()}</div></section></div><details class="rules-inline"><summary>Как считается шанс</summary><p>Суммарная стоимость предметов и добавленных монет / стоимость цели × 0,93. Максимальный шанс — 75%. Голубая зона заполняется снизу вверх и показывает область успеха. При победе цель поступает в инвентарь; при неудаче ставка теряется.</p></details>`}
function quickTarget(percent){const inv=state.inventory.find(i=>i.uid===selection.upgrade);if(!inv)return toast('Сначала выбери свою ставку',true);const desired=upgradeStake(inv)*(1-CONFIG.upgradeEdge)/(percent/100);const pool=CONFIG.items.filter(p=>value(p.id)>value(inv.id));if(!pool.length)return toast('Нет цели дороже этого предмета',true);selection.target=pool.reduce((a,b)=>Math.abs(value(a.id)-desired)<Math.abs(value(b.id)-desired)?a:b).id;render()}
function upgrade(){if(busy)return;const target=itemById(selection.target),inv=state.inventory.find(i=>i.uid===selection.upgrade);if(!target||!inv||value(target.id)<=value(inv.id))return toast('Выбери более дорогую цель',true);const coins=round(Number(upgradeCoins));if(!Number.isFinite(coins)||coins<0||coins>state.balance)return toast('Проверь монеты к ставке',true);const chance=upgradeProbability(inv,target),i=takeItem('upgrade');if(!i)return;state.balance=round(state.balance-round(coins));upgradeCoins=0;busy=true;upgradeFeedback=null;state.stats.upgrades++;state.stats.played++;log('upgrade','Ставка: '+itemById(i.id).name+(coins?' + '+fmt(coins)+' R':''),-round(coins));const won=random()<chance,half=Math.acos(1-2*chance)*180/Math.PI,landing=won?(180-half+2*half*(.15+random()*.7))%360:(180+half+(360-2*half)*(.15+random()*.7))%360,from=((upgradeAngle%360)+360)%360;upgradeAngle=from+1800+((landing-from+360)%360);const pointer=$('#upgradePointer');pointer.style.transition='transform '+(fastSpin?'.8':'3.8')+'s cubic-bezier(.10,.62,.12,1)';requestAnimationFrame(()=>pointer.style.transform=`rotate(${upgradeAngle}deg)`);$('#upgradeGo').textContent='Апгрейд…';$$('.upgrade-workspace button,.upgrade-workspace input,.upgrade-workspace select').forEach(b=>b.disabled=true);SFX.play('start');const ticking=SFX.ticks(fastSpin?700:3600);
 setTimeout(()=>{clearInterval(ticking);if(won){const prize=makeInv(target.id);state.inventory.push(prize);publishDrop(target.id,'Апгрейд');selection.upgrade=prize.uid;selection.target=null}upgradeFeedback={win:won,chance:chance*100,text:won?target.name+' добавлен в инвентарь':'Неудача · предмет потерян'};upgradeAngle=((upgradeAngle%360)+360)%360;busy=false;log('upgrade',won?'Успех → '+target.name:'Неудача');render();SFX.play(won?'win':'lose');toast(won?target.name+' в инвентаре':'Апгрейд не удался · предмет потерян')},fastSpin?900:3900)}
function renderCrash(){return `${title('Краш','Ставка предметом, выплата монетами по текущему множителю.')}<div class="game-layout"><section class="panel"><h3>Предмет для полёта</h3>${selectedBox('crash')}<div class="stat-line"><span>Текущий множитель</span><strong id="crashSideMult">x1.00</strong></div><div class="stat-line"><span>Можно забрать</span><strong id="crashReturn">0 R</strong></div><button class="btn wide" data-action="crash" id="crashAction" ${!selection.crash?'disabled':''}>Начать полёт ${icon('rocket')}</button><div class="divider"></div><p class="muted-small">Предмет списывается в начале полёта. Успешный выход начисляет его стоимость × множитель в монетах. Ракета может остановиться сразу.</p></section><section class="panel game-stage crash-stage" id="crashStage"><div class="crash-grid"></div><div class="rocket">${icon('rocket')}</div><div class="multiplier" id="crashMult">1.00<span style="color:var(--lime)">×</span></div></section></div>${inlineInventory('crash','Мои предметы')}`}
function crashStart(){if(crash.active)return crashCashout();if(busy)return;const i=takeItem('crash');if(!i)return;crash={active:true,mult:1,point:Math.max(1,Math.min(50,Math.floor(.96/(1-random())*100)/100)),bet:value(i.id),timer:null,started:performance.now()};state.stats.crash=(state.stats.crash||0)+1;state.stats.played++;log('crash','В полёте: '+itemById(i.id).name);SFX.play('start');$('#crashStage').classList.add('running');$('#crashAction').textContent='Забрать монеты';crash.timer=setInterval(()=>{const next=Math.exp((performance.now()-crash.started)/10000);if(next>=crash.point){crash.mult=crash.point;crashEnd(false);return}crash.mult=next;updateCrash()},70)}
function updateCrash(){$('#crashMult').textContent=crash.mult.toFixed(2)+'×';$('#crashSideMult').textContent='x'+crash.mult.toFixed(2);$('#crashReturn').textContent=fmt(Math.floor(crash.bet*crash.mult*100)/100)+' R'}
function crashCashout(){if(!crash.active)return;crash.mult=Math.exp((performance.now()-crash.started)/10000);if(crash.mult>=crash.point){crash.mult=crash.point;return crashEnd(false)}crashEnd(true)}
function crashEnd(win){if(!crash.active)return;clearInterval(crash.timer);crash.active=false;const payout=win?Math.floor(crash.bet*crash.mult*100)/100:0;state.balance=round(state.balance+payout);updateCrash();$('#crashStage').classList.remove('running');$('#crashStage').classList.toggle('exploded',!win);$('#crashAction').textContent='Следующий полёт';$('#crashAction').dataset.action='reset-game';if(win)publishDrop(null,'Краш',1,payout);recordGameResult('crash',crash.bet,payout);log('crash',win?'Выход x'+crash.mult.toFixed(2):'Краш x'+crash.point.toFixed(2),payout);SFX.play(win?'win':'lose');toast(win?'Забрано '+fmt(payout)+' R · x'+crash.mult.toFixed(2):'Краш x'+crash.point.toFixed(2)+' · предмет потерян')}
function historyTable(){return state.history.length?`<div class="table-wrap"><table><thead><tr><th>ОПЕРАЦИЯ</th><th>ВРЕМЯ</th><th>БАЛАНС</th></tr></thead><tbody>${state.history.slice(0,20).map(h=>`<tr><td>${esc(h.text)}</td><td>${new Date(h.at).toLocaleTimeString('ru-RU',{hour:'2-digit',minute:'2-digit'})}</td><td class="${h.amount>0?'positive':h.amount<0?'negative':''}">${h.amount>0?'+':''}${h.amount?fmt(h.amount)+' R':'—'}</td></tr>`).join('')}</tbody></table></div>`:'<p class="subtle">Твои открытия, обмены и результаты появятся здесь.</p>'}
function renderBonuses(){return '<p class="subtle">Бонусы</p>';}
function renderProfile(){return `<div class="profile-head"><div class="avatar">D</div><div><h1 class="page-title">Demo Player</h1><span class="subtle">Локальный профиль · #0001</span></div></div><div class="mobile-profile-tools"><button class="btn secondary" data-page="admin">${icon('sliders')}Студия</button><button class="btn secondary" data-page="faq">${icon('help')}Правила</button></div><section class="panel audio-settings"><div><strong>Звук</strong><span id="audioVolumeValue">${Math.round(SFX.volume*100)}%</span></div><input id="audioVolume" aria-label="Громкость звука" type="range" min="0" max="100" value="${Math.round(SFX.volume*100)}"><button class="btn secondary" data-action="audio-test">Проверить</button></section><div class="stats-grid">${[['box',state.stats.cases,'Кейсов открыто'],['arrow',state.stats.upgrades,'Апгрейдов сделано'],['bag',state.inventory.length,'Предметов'],['wallet',fmt(state.stats.withdrawn)+' R','Выведено реально']].map(([i,v,n])=>`<div class="stat-card">${icon(i)}<strong>${v}</strong><span>${n}</span></div>`).join('')}</div><div class="two-cols"><section class="panel"><div class="panel-heading"><h3>Реферальный кабинет</h3>${icon('users')}</div><div class="ref-profile-total">${fmt(state.referrals.available)} <small>R</small></div><p class="subtle">Доступно к переводу · ${state.referrals.people.length} приглашённых</p><button class="btn secondary wide" data-page="referrals">Открыть кабинет ${icon('chevron')}</button></section><section class="panel"><h3>Твои заявки</h3>${state.withdrawals.length?state.withdrawals.map(w=>`<div class="stat-line"><span>${esc(itemById(w.item.id).name)}<br><small>${new Date(w.time).toLocaleString('ru-RU')} · ${w.status}</small></span><button class="btn secondary" data-cancel="${w.id}">Отмена</button></div>`).join(''):'<p class="subtle">Здесь будут тестовые заявки на получение предметов.</p>'}</section></div><section class="panel" style="margin-top:20px"><h3>Последние операции</h3>${historyTable()}</section>`}
function renderAdmin(){return `${title('Студия','Демо-настройки каталога и баланса. Изменения сохраняются в этом браузере.')}<div class="notice">В этой демке настройки открыты для просмотра. Проверка владельца появится только с сервером.</div><div class="two-cols"><section class="panel"><h3>Экономика</h3><div class="form-grid"><label>Реферальный процент<input id="adminRef" type="number" min="0" max="100" value="${state.settings.referralPercent}"></label><label>Бонус по промокоду, %<input id="adminPromo" type="number" min="0" max="100" value="${state.settings.promoBonus}"></label><label>Партнёру с пополнения, %<input id="adminPartner" type="number" min="0" max="100" value="${state.settings.partnerBonus}"></label><label>Курс Stars<span class="currency-rate"><span class="coin">R</span>1 = 1.5 Stars</span></label></div><button class="btn" style="margin-top:20px" data-action="save-settings">Сохранить</button><div class="divider"></div><h3>Тестовый баланс</h3><div class="copy-row"><input id="adminMoney" type="number" min="1" value="1000" aria-label="Сумма начисления"><button class="btn secondary" data-action="admin-money">Добавить</button></div></section><section class="panel"><h3>Предметы · ${CONFIG.items.length}</h3><label class="label" for="adminItem">Выбери предмет</label><select id="adminItem" class="select-full">${CONFIG.items.map(p=>`<option value="${p.id}">${esc(p.name)}</option>`).join('')}</select><label class="label" for="adminPrice">Цена в монетах</label><input class="select-full" id="adminPrice" type="number" min="1" value="${value(CONFIG.items[0].id)}"><div class="inline-actions"><button class="btn" data-action="save-price">Сохранить цену</button><button class="btn secondary" data-action="grant-item">Выдать себе</button></div><label class="label" for="adminCase">Стоимость кейса</label><div class="stack"><select id="adminCase" class="select-full">${CONFIG.cases.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select><input id="adminCasePrice" type="number" min="1" value="${casePrice(CONFIG.cases[0])}"><button class="btn secondary" data-action="save-case-price">Сохранить стоимость</button></div></section></div><section class="panel" style="margin-top:20px"><h3>Данные демки</h3><p class="subtle">Каталог, шансы и картинки редактируются в config.js. Можно сохранить текущий прогресс в JSON или начать заново.</p><div class="inline-actions"><button class="btn secondary" data-action="export">${icon('external')}Экспорт прогресса</button><button class="btn danger" data-action="reset">${icon('trash')}Сбросить демку</button></div></section>`}
function renderFAQ(){return `${title('Как всё устроено','Правила демки и ответы на основные вопросы.')}<section class="panel" style="margin-top:24px">${[
 ['Что это за версия?','Локальная интерактивная демка. Все предметы и монеты тестовые, не имеют денежной стоимости. Платежи, реальные пополнения и выдача предметов не выполняются.'],
 ['Как работают кейсы?','Стоимость списывается с тестового баланса. Один предмет выбирается по опубликованным шансам и сразу добавляется в инвентарь. Каждый кейс содержит восемь предметов.'],
 ['Какие правила Color Dice?','Ставишь до 5 предметов и выбираешь цвет. Выпадает четыре независимых кубика, у каждого шесть равновероятных цветов. Ровно одно или четыре совпадения дают два экземпляра каждого поставленного предмета в инвентарь. Иначе предмет теряется. Шанс победы по этим правилам — около 38,66%.'],
 ['Как играть в мины?','Поле 5 × 5. Выбери количество мин и ставку в монетах. Каждая безопасная клетка повышает множитель. Нажми «Забрать выигрыш», чтобы закончить раунд. Мина теряет ставку. Коэффициент рассчитывается из вероятности выживания с демо-маржой 6%.'],
 ['Чем апгрейдер отличается от краша?','В апгрейдере меняешь предмет на более дорогой с указанным шансом. В краше ставишь предмет и забираешь его растущую стоимость в монетах до остановки ракеты. Шанс апгрейда — отношение цен × 0,93, максимум 75%.'],
 ['Как работают обмен и вывод?','Обмен выдаёт до 5 более дешёвых предметов одного выбранного вида. Количество — целая часть отношения цен, максимум 5. Неиспользованная стоимость возвращается монетами на баланс; доплата от игрока не требуется. Каждый третий предмет в демонстрационном каталоге доступен для тестовой записи на вывод. Интервалы идут с шагом четыре минуты. Заявку можно отменить, вернув предмет.'],
 ['Что с рефералами и промокодами?','Предложенные правила: партнёру процент от положительного чистого проигрыша реферала за период, без бонусных начислений. Промокод даёт бонус пользователю, партнёру — отдельный процент. В демке можно посмотреть настройки и применить код ROT; реальное начисление партнёру не выполняется.'],
 ['Сохранится ли прогресс?','Да, в localStorage этого браузера, если хранилище доступно. В другом браузере или на другом устройстве будет отдельная демка. Очистка данных браузера удалит прогресс.']
 ].map(([q,a])=>`<details class="faq-item"><summary>${q}</summary><p>${a}</p></details>`).join('')}</section>`}
function deposit(){showModal(`<h2 id="dialogTitle">Добавить тестовый баланс</h2><p class="subtle">Выбери способ, чтобы посмотреть сценарий пополнения.</p><div class="tabs" style="margin:22px 0"><button class="chip active" data-deposit-tab="stars">${icon('star')} Stars</button><button class="chip" data-deposit-tab="items">${icon('box')} Предметы</button></div><div id="depositBody">${depositForm()}</div>`)}
function depositForm(){return `<label class="label" for="depositAmount">Сколько монет добавить</label><input id="depositAmount" class="select-full" type="number" min="1" max="1000000" value="500"><div class="stat-line"><span>По курсу 1 R = 1,5 Stars</span><strong id="starCost">750 Stars</strong></div><label class="label" for="promo">Промокод</label><input class="select-full" id="promo" placeholder="Попробуй ROT"><div class="notice">Демонстрация. Stars не списываются. Кнопка добавляет только тестовые монеты.</div><button class="btn wide" data-action="deposit">Начислить тестовые монеты</button>`}
function doDeposit(){const n=Number($('#depositAmount').value);if(!Number.isFinite(n)||n<1||n>1e6)return toast('Введи сумму от 1 до 1 000 000',true);const promo=$('#promo').value.trim().toUpperCase(),percent=promo?(typeof depositPromo==='function'?depositPromo(promo):(promo==='ROT'?state.settings.promoBonus:null)):0;if(percent===null)return toast('Промокод недоступен',true);const bonus=round(n*percent/100);state.balance=round(state.balance+n+bonus);log('deposit','Тестовое пополнение'+(bonus?' · бонус '+fmt(bonus)+' R':''),n+bonus);closeModal();render();toast('Начислено '+fmt(n+bonus)+' тестовых монет')}
function cancelBooking(id){const index=state.withdrawals.findIndex(w=>w.id===id);if(index<0)return;const w=state.withdrawals.splice(index,1)[0];state.inventory.push(w.item);log('withdraw','Отмена тестовой заявки');render();toast('Предмет возвращён в инвентарь')}
function num(id,min=0,max=100){const n=Number($(id).value);return Number.isFinite(n)&&n>=min&&n<=max?n:null}
document.addEventListener('click',async e=>{const b=e.target.closest('button,[data-close]');if(!b||b.disabled)return;const d=b.dataset;if(b.dataset.action!=='sound-toggle')SFX.play('tap');
 if(d.inlineSelect){if(busy||crash.active)return;selection[d.kind]=d.inlineSelect;if(d.kind==='upgrade'){upgradeTab='target';selection.target=null;upgradeFeedback=null;upgradeAngle=0}if(d.kind==='dice')diceFeedback=null;render();return}
 if(d.upgradeTab){if(busy)return;upgradeTab=d.upgradeTab;$('.upgrade-workspace').dataset.tab=upgradeTab;$$('[data-upgrade-tab]').forEach(x=>x.classList.toggle('active',x.dataset.upgradeTab===upgradeTab));return}
 if(d.inlineTarget){if(busy)return;selection.target=d.inlineTarget;upgradeFeedback=null;upgradeAngle=0;render();if(window.matchMedia?.('(max-width:580px)').matches)requestAnimationFrame(()=>document.querySelector('.upgrade-console')?.scrollIntoView({behavior:'smooth',block:'start'}));return}
 if(d.refRange){refRange=d.refRange;render();return}

 if('close'in d)return closeModal();if(d.page){closeModal();return go(d.page)}if(d.category){category=d.category;return render()};if(d.case)return openCase(d.case);if(d.open)return rollCase(d.open);if(d.inv)return viewItem(d.inv);if(d.sell)return sell(d.sell);if(d.exchange)return exchange(d.exchange);if(d.exchangeTo)return doExchange(d.source,d.exchangeTo);if(d.withdraw)return withdraw(d.withdraw);if(d.book)return book(d.book,d.time);if(d.cancel)return cancelBooking(d.cancel);if(d.pick){if(['dice','crash','upgrade'].includes(d.pick)){document.querySelector('#list-'+d.pick)?.scrollIntoView({behavior:'smooth',block:'center'});return}return pick(d.pick)}
 if(d.select){selection[d.kind]=d.select;if(d.kind==='upgrade')selection.target=null;closeModal();return render()}if(d.target){selection.target=d.target;upgradeFeedback=null;upgradeAngle=0;closeModal();return render()}if(d.color!==undefined){diceColor=Number(d.color);diceFeedback=null;return render()}if(d.quick)return quickTarget(Number(d.quick));if(d.tile!==undefined)return mineTile(Number(d.tile));if(d.depositTab){$$('[data-deposit-tab]').forEach(x=>x.classList.toggle('active',x===b));$('#depositBody').innerHTML=d.depositTab==='stars'?depositForm():`<div class="notice">Приём предметов подключим позже. В демке ничего передавать в игре не нужно.</div><p class="subtle">Здесь владелец разместит инструкции и условия передачи.</p>`;return}
 switch(d.action){case'audio-test':SFX.test();toast('Проверка звука');break;case'show-deposit':deposit();break;case'sound-toggle':SFX.toggle();break;case'ref-transfer':refTransfer();break;case'copy-code':try{await navigator.clipboard.writeText(state.referrals.code);toast('Код скопирован')}catch{toast('Твой код: '+state.referrals.code)}break;case'ref-help':showModal(refHelp());break;case'featured':openCase(CONFIG.cases[0].id);break;case'roll-dice':rollDice();break;case'mine-start':mineStart();break;case'upgrade':upgrade();break;case'crash':crashStart();break;case'reset-game':render();break;case'deposit':doDeposit();break;case'copy-ref':try{await navigator.clipboard.writeText('https://t.me/your_bot/app?startapp='+state.referrals.code);toast('Ссылка скопирована')}catch{toast('Выдели ссылку и скопируй вручную')}break;
 case'save-settings':{const a=num('#adminRef'),b=num('#adminPromo'),c=num('#adminPartner');if([a,b,c].includes(null))return toast('Проценты должны быть от 0 до 100',true);state.settings={referralPercent:a,promoBonus:b,partnerBonus:c};save();toast('Настройки сохранены');break}
 case'admin-money':{const n=num('#adminMoney',1,1e9);if(n===null)return toast('Проверь сумму',true);state.balance=round(state.balance+n);log('admin','Тестовое начисление',n);toast('Баланс обновлён');break}
 case'save-price':{const n=num('#adminPrice',1,1e12);if(n===null)return toast('Проверь цену',true);state.prices[$('#adminItem').value]=n;save();toast('Цена обновлена');break}
 case'grant-item':state.inventory.push(makeInv($('#adminItem').value));log('admin','Тестовая выдача предмета');toast('Предмет добавлен');break;
 case'save-case-price':{const n=num('#adminCasePrice',1,1e12);if(n===null)return toast('Проверь стоимость',true);state.casePrices[$('#adminCase').value]=n;save();toast('Стоимость кейса обновлена');break}
 case'export':{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='rot-demo-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);break}
 case'reset':showModal('<h2 id="dialogTitle">Начать сначала?</h2><p class="subtle">Сбросятся тестовый баланс, коллекция, история и настройки в этом браузере.</p><button class="btn danger" data-action="confirm-reset">Да, сбросить демку</button>');break;
 case'confirm-reset':state=fresh();selection={dice:null,upgrade:null,target:null,crash:null};upgradeCoins=0;if(typeof ensureDemoFeatures==='function')ensureDemoFeatures();ensureReferralState();upgradeFeedback=null;diceFeedback=null;save();closeModal();render();toast('Демка сброшена');break;
 }
});
document.addEventListener('input',e=>{if(e.target.id==='audioVolume'){SFX.setVolume(Number(e.target.value)/100);const v=$('#audioVolumeValue');if(v)v.textContent=e.target.value+'%';}if(e.target.dataset.picker){const kind=e.target.dataset.picker;pickerFilters[kind]=e.target.value;const list=$('#list-'+kind);if(list)list.innerHTML=kind==='target'?targetCards():inventoryCards(kind)}if(e.target.id==='caseSearch'){query=e.target.value;filterCases()}if(e.target.id==='depositAmount')$('#starCost').textContent=fmt(Math.max(0,Number(e.target.value)||0)*CONFIG.starsPerMoney)+' Stars'});
document.addEventListener('change',e=>{if(e.target.id==='audioVolume')SFX.play('tap');if(e.target.dataset.pickerSort){const kind=e.target.dataset.pickerSort;pickerFilters[kind+'Sort']=e.target.value;const list=$('#list-'+kind);if(list)list.innerHTML=kind==='target'?targetCards():inventoryCards(kind)}if(e.target.id==='caseSort'){sort=e.target.value;filterCases()}if(e.target.id==='adminItem')$('#adminPrice').value=value(e.target.value);if(e.target.id==='adminCase')$('#adminCasePrice').value=casePrice(CONFIG.cases.find(c=>c.id===e.target.value))});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();if(e.key==='Tab'&&!$('#modal').hidden){const a=[...$('#modal').querySelectorAll('button:not(:disabled),input,select,[tabindex="0"]')].filter(x=>x.offsetParent!==null),first=a[0],last=a.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});
$('#balanceBtn').addEventListener('click',()=>{if(busy||mine.active||crash.active)return toast('Сначала заверши раунд');deposit()});
window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(p!==page&&!busy&&!mine.active&&!crash.active){ensureReferralState();
SFX.update();
page=[...NAV.map(x=>x[0]),'admin','faq'].includes(p)?p:'cases';render()}});
window.addEventListener('beforeunload',e=>{if(busy||mine.active||crash.active){e.preventDefault();e.returnValue=''}});
ensureReferralState();
SFX.update();
page=[...NAV.map(x=>x[0]),'admin','faq'].includes(location.hash.slice(1))?location.hash.slice(1):'cases';render();






